    "captured_at": "2026-10-17",
    "source": "Google Flights Deals public UI",
    "query": "Viagens internacionais para fora do Brasil de 3 a 14 dias em qualquer data disponível"
  }
}
});

return (function execute({ nodes }, { queries, settings }) {
  const configuration = nodes.configuration.first().json;
  return settings.categories.flatMap((category) =>
    settings.origins.map((origin) => ({
      json: {
        ...configuration,
        category,
        origin,
        searchedAt: configuration.searchedAt,
        today: configuration.today,
        url: queries.makeQuery(category, origin, configuration),
      },
    })),
  );
})({ input: $input, now: $now, nodes: { configuration: $("Interpretar pedido") } }, { queries: queries, settings: settings });

